const wsUrl = 'ws://localhost:8080'
const io_id = 'frontend'
let ws

const _ = {} // senders mapping
const $ = {} // receivers mapping

const io = {
  get send() { return _['backend'] },
  on: {},
  get status() { return ws ? ws.readyState : null },
  OPEN: typeof window !== 'undefined' && window.WebSocket ? window.WebSocket.OPEN : 1
}

function add(name, tx, to, rx, $) {
  const { state } = $[to] = { rx, tx, state: { name, to, mid: 0 } }
  _[name] = send

  function send(type, data = {}, refs = {}) {
    const head = [io_id, to, state.mid++]
    const meta = { time: Date.now(), stack: (new Error().stack) }
    tx({ head, refs, type, data, meta })
    return head
  }
}

function tx(msg) {
  if (!ws || ws.readyState !== window.WebSocket.OPEN) {
    console.warn(`io module: WebSocket not ready for ${msg.type} (Status: ${ws ? ws.readyState : 'null'})`)
    return
  }
  ws.send(JSON.stringify(msg))
}

function rx(m) {
  for (const [key, handler] of Object.entries(io.on)) {
    if (typeof handler === 'function') {
      try { handler(m) } catch (err) { console.error(`io handler '${key}' error:`, err) }
    }
  }
}

function connect() {
  try {
    if (typeof window === 'undefined' || !window.WebSocket) return;

    ws = new window.WebSocket(wsUrl)

    ws.onopen = () => {
      console.log('io module: ✅ Connected to', wsUrl)
    }

    ws.onclose = () => {
      console.log('io module: ❌ Disconnected — retrying in 2s...')
      setTimeout(connect, 2000)
    }

    ws.onerror = (err) => {
      console.error('io module: ⚠️ WebSocket error:', err)
    }

    ws.onmessage = (ev) => {
      const m = JSON.parse(ev.data)
      if ($['backend'] && typeof $['backend'].rx === 'function') {
        $['backend'].rx(m)
      }
    }
  } catch (err) {
    console.error('io module connect error:', err);
  }
}

add('backend', tx, 'backend', rx, $)
connect()

module.exports = io

// ============ Fallback Setup for STATE ============
function fallback_module() {
  return {
    api: fallback_instance
  }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return {
      drive: {
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {}
    }
  }
}

